            let three = f32x16::splat_t(t, 3.0);
            let twelve = f32x16::splat_t(t, 12.0);
            let hlg_a_ln2 = f32x16::splat_t(t, HLG_A_INV_LOG2E);
            let hlg_b = f32x16::splat_t(t, HLG_B);
            let hlg_c = f32x16::splat_t(t, HLG_C);
