            let small = a.simd_lt(f32x4::splat_t(t, 0.25));
            let p = polynomial::eval_blended_poly_x4(
                t,
                x,
                small,
                PQ_EOTF_P_SMALL,
                PQ_EOTF_P_LARGE,
            );
            let q = polynomial::eval_blended_poly_x4(
                t,
                x,
                small,
                PQ_EOTF_Q_SMALL,
                PQ_EOTF_Q_LARGE,
            );
